                </p>
                <div className="flex justify-center gap-4">
                  <Button
                    onClick={() =>
                      (document.querySelector('[value="templates"]') as HTMLElement)?.click()
                    }
                  >
                    Chọn Template
                  </Button>
                  <Button
                    variant="outline"
                    onClick={() =>
                      (document.querySelector('[value="presets"]') as HTMLElement)?.click()
                    }
                  >
                    Chọn Preset
