                      <h3 className="mb-2 text-lg font-semibold">{preset.name}</h3>
                      <p className="mb-4 text-sm text-gray-600">{preset.description}</p>
                      <div className="flex items-center justify-between">
                        <div className="text-sm text-gray-500">
                          {preset.config.zones.length} khu vực
                        </div>
                        <Button
                          size="sm"
                          onClick={() => handleApplyPreset(preset)}
                          disabled={saving}
                        >
                          Áp dụng
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

'use client';
import * as z from 'zod';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useRouter } from 'next/navigation';
import { post, patch } from '@/lib/api';
import { toast } from 'sonner';
import { useState } from 'react';
import { Loader2 } from 'lucide-react';
import { ImageUpload } from '@/components/common/ImageUpload';
const bannerSchema = z.object({
  title: z.string().optional(),
  imageUrl: z.string().url('Vui lòng nhập URL ảnh hợp lệ'),
  mobileImageUrl: z.string().url('Vui lòng nhập URL ảnh hợp lệ').optional().or(z.literal('')),
  actionLink: z.string().optional(),
  position: z.enum(['HOME_MAIN_SLIDER', 'HOME_MID_SECTION', 'POPUP', 'SIDEBAR']),
  displayOrder: z.coerce.number().min(0),
  isActive: z.boolean().default(true),
  startTime: z.string().optional(),
  endTime: z.string().optional(),
});
type BannerFormValues = z.infer<typeof bannerSchema>;
interface BannerFormProps {
  initialData?: BannerFormValues & {
    id?: number;
  };
  isEdit?: boolean;
}
export function BannerForm({ initialData, isEdit }: BannerFormProps) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const form = useForm<BannerFormValues>({
    resolver: zodResolver(bannerSchema),
    defaultValues: {
      title: initialData?.title || '',
      imageUrl: initialData?.imageUrl || '',
      mobileImageUrl: initialData?.mobileImageUrl || '',
      actionLink: initialData?.actionLink || '',
      position: (initialData?.position as any) || 'HOME_MAIN_SLIDER',
      displayOrder: initialData?.displayOrder ?? 0,
      isActive: initialData?.isActive ?? true,
      startTime: initialData?.startTime
        ? new Date(initialData.startTime).toISOString().slice(0, 16)
        : undefined,
      endTime: initialData?.endTime
        ? new Date(initialData.endTime).toISOString().slice(0, 16)
        : undefined,
    },
  });
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = form;
  const onSubmit = async (data: BannerFormValues) => {
    setLoading(true);
    try {
      if (isEdit && initialData?.id) {
        await patch(`/banners/admin/${initialData.id}`, data);
        toast.success('Cập nhật banner thành công');
      } else {
        await post('/banners/admin', data);
        toast.success('Tạo banner thành công');
      }
      router.push('/admin/banners');
      router.refresh();
    } catch (error) {
      toast.error('Có lỗi xảy ra');
    } finally {
      setLoading(false);
    }
  };
  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="max-w-2xl space-y-6 rounded-lg border bg-white p-6 shadow-sm"
