import axios, { AxiosError, InternalAxiosRequestConfig } from 'axios';
import { useAuthStore } from '@/stores/auth.store';
const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3001/api/v1';
const pendingRequests = new Map<string, Promise<any>>();
function getRequestKey(config: any): string {
  return `${config.method}-${config.url}-${JSON.stringify(config.params || {})}-${JSON.stringify(config.data || {})}`;
}
export const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 8000,
});
api.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = useAuthStore.getState().accessToken;
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    } else {
    }
    const requestKey = getRequestKey(config);
    const pendingRequest = pendingRequests.get(requestKey);
    if (pendingRequest) {
      return Promise.reject({ __CANCEL__: true, pendingRequest });
    }
    return config;
  },
  (error) => Promise.reject(error)
);
api.interceptors.response.use(
  (response) => {
    const requestKey = getRequestKey(response.config);
    pendingRequests.delete(requestKey);
    return response;
  },
  async (error: any) => {
    if (error.__CANCEL__) {
      return error.pendingRequest;
    }
    const axiosError = error as AxiosError;
    const originalRequest = axiosError.config as InternalAxiosRequestConfig & {
      _retry?: boolean;
    };
    const responseData = axiosError.response?.data as any;
    if (originalRequest) {
      const requestKey = getRequestKey(originalRequest);
      pendingRequests.delete(requestKey);
    }
    const isSessionExpired =
      axiosError.response?.status === 401 || responseData?.code === 'AUTH_002';
    if (isSessionExpired && originalRequest && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        const refreshToken = useAuthStore.getState().refreshToken;
        if (refreshToken) {
          const response = await axios.post(`${API_URL}/auth/refresh-token`, {
            refreshToken,
          });
          const { accessToken, refreshToken: newRefreshToken } = response.data.data;
          useAuthStore.getState().setTokens(accessToken, newRefreshToken);
          originalRequest.headers.Authorization = `Bearer ${accessToken}`;
          return api(originalRequest);
        } else {
          throw new Error('No refresh token');
        }
      } catch (refreshError) {
        useAuthStore.getState().logout();
        if (typeof window !== 'undefined') {
          if (window.location.pathname !== '/login') {
            window.location.href = `/login?redirect=${encodeURIComponent(window.location.pathname + window.location.search)}`;
          }
        }
      }
    }
    return Promise.reject(axiosError);
  }
);
export interface ApiResponse<T> {
  success: boolean;
  data: T | null;
  message: string;
  code: string;
  timestamp: string;
  path: string;
}
export interface PaginatedResponse<T> extends ApiResponse<T[]> {
  meta: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}
export async function get<T>(url: string): Promise<T> {
  const requestKey = `GET-${url}--`;
  if (pendingRequests.has(requestKey)) {
    return pendingRequests.get(requestKey);
  }
  const requestPromise = (async () => {
    try {
      const response = await api.get<T | ApiResponse<T>>(url);
      if (
        response.data &&
        typeof response.data === 'object' &&
        'data' in response.data &&
        'success' in response.data
      ) {
        const apiResponse = response.data as ApiResponse<T> & {
          meta?: {
            page: number;
            limit: number;
            total: number;
            totalPages: number;
          };
        };
        if (!apiResponse.success) {
          throw new Error(apiResponse.message || 'API Error');
        }
        if ('meta' in apiResponse && apiResponse.meta) {
          return { items: apiResponse.data, meta: apiResponse.meta } as T;
        }
        return apiResponse.data as T;
      }
      return response.data as T;
    } finally {
      pendingRequests.delete(requestKey);
    }
  })();
  pendingRequests.set(requestKey, requestPromise);
  return requestPromise;
}
export async function post<T, D = unknown>(url: string, data?: D): Promise<T> {
  const response = await api.post<T | ApiResponse<T>>(url, data);
  if (
    response.data &&
    typeof response.data === 'object' &&
    'data' in response.data &&
    'success' in response.data
  ) {
    return (response.data as ApiResponse<T>).data as T;
  }
  return response.data as T;
}
export async function put<T, D = unknown>(url: string, data?: D): Promise<T> {
  const response = await api.put<T | ApiResponse<T>>(url, data);
  if (
    response.data &&
    typeof response.data === 'object' &&
    'data' in response.data &&
    'success' in response.data
  ) {
    return (response.data as ApiResponse<T>).data as T;
  }
  return response.data as T;
}
export async function patch<T, D = unknown>(url: string, data?: D): Promise<T> {
  const response = await api.patch<T | ApiResponse<T>>(url, data);
  if (
    response.data &&
    typeof response.data === 'object' &&
    'data' in response.data &&
    'success' in response.data
  ) {
    return (response.data as ApiResponse<T>).data as T;
  }
  return response.data as T;
}
export async function del<T>(url: string): Promise<T> {
  const response = await api.delete<T | ApiResponse<T>>(url);
  if (
    response.data &&
    typeof response.data === 'object' &&
    'data' in response.data &&
    'success' in response.data
  ) {
    return (response.data as ApiResponse<T>).data as T;
  }
  return response.data as T;
}
export async function upload<T>(url: string, formData: FormData): Promise<T> {
  const response = await api.post<T | ApiResponse<T>>(url, formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
  if (
    response.data &&
    typeof response.data === 'object' &&
    'data' in response.data &&
    'success' in response.data
  ) {
    return (response.data as ApiResponse<T>).data as T;
  }
  return response.data as T;
}

import { api } from '@/lib/api';
export interface BankQRRequest {
  bankCode: string;
  accountNumber: string;
  accountName: string;
  amount?: number;
  description?: string;
}
export interface BankQRResponse {
  qrBase64: string;
  qrContent: string;
  deeplink: string | null;
  bankCode: string;
  bankName: string;
  accountNumber: string;
  accountName: string;
  amount?: number;
  description?: string;
}
export interface QRPaymentRequest {
  amount?: number;
  description?: string;
}
export interface QRPaymentResponse {
  success: boolean;
  qrImageBase64: string;
  qrImageUrl?: string;
  qrContent: string;
  bank: {
    bankCode: string;
    bankName: string;
    accountNumber: string;
    accountName: string;
  };
  amount?: number;
  description?: string;
  deeplink?: string;
}
export interface BankInfo {
  code: string;
  name: string;
  shortName: string;
  logo?: string;
  deeplinkScheme?: string;
}
export interface QRValidationResponse {
  isValid: boolean;
  data?: {
    bankCode: string;
    accountNumber: string;
    accountName: string;
    amount?: number;
    description?: string;
  };
  error?: string;
}
class PaymentService {
  private readonly baseUrl = '/payment';
  async generateBankQR(data: BankQRRequest): Promise<BankQRResponse> {
    const response = await api.post(`${this.baseUrl}/generate-custom-qr`, data);
    return response.data.data;
  }
  async generateQRPayment(data: QRPaymentRequest): Promise<QRPaymentResponse> {
    const response = await api.post(`${this.baseUrl}/generate-qr`, data);
    return response.data;
  }
  async generateQRImage(params: BankQRRequest): Promise<Blob> {
    const queryParams = new URLSearchParams();
    queryParams.append('bankCode', params.bankCode);
    queryParams.append('accountNumber', params.accountNumber);
    queryParams.append('accountName', params.accountName);
    if (params.amount) queryParams.append('amount', params.amount.toString());
    if (params.description) queryParams.append('description', params.description);
    const response = await api.get(`${this.baseUrl}/qr-image?${queryParams.toString()}`);
    const { qrBase64 } = response.data.data;
    const base64Data = qrBase64.split(',')[1];
    const byteCharacters = atob(base64Data);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    return new Blob([byteArray], { type: 'image/png' });
  }
  async getSupportedBanks(): Promise<Record<string, BankInfo>> {
    const response = await api.get(`${this.baseUrl}/banks`);
    return response.data.data;
  }
  async validateQR(qrString: string): Promise<QRValidationResponse> {
    const response = await api.post(`${this.baseUrl}/validate-qr`, { qrString });
    return response.data.data;
  }
  async getTestQR(): Promise<BankQRResponse> {
    const response = await api.get(`${this.baseUrl}/test-qr`);
    return response.data.data;
  }
  async healthCheck(): Promise<{
    message: string;
    supportedBanks: number;
  }> {
    const response = await api.get(`${this.baseUrl}/health`);
    return response.data.data;
  }
  downloadQRImage(blob: Blob, filename: string = 'qr-code.png') {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  }
  async copyToClipboard(text: string): Promise<boolean> {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (err) {
      const textArea = document.createElement('textarea');
      textArea.value = text;
      document.body.appendChild(textArea);
      textArea.select();
      const success = document.execCommand('copy');
      document.body.removeChild(textArea);
      return success;
    }
  }
  async shareQR(data: BankQRResponse): Promise<boolean> {
    if (!navigator.share) {
      return false;
    }
    try {
      await navigator.share({
        title: 'Mã QR Thanh Toán',
        text: `Thanh toán cho ${data.bankName} - ${data.accountName}${data.amount ? ` - ${data.amount.toLocaleString('vi-VN')} VND` : ''}`,
        url: data.deeplink || undefined,
      });
      return true;
    } catch (err) {
      return false;
    }
  }
  openBankApp(deeplink: string): void {
    const link = document.createElement('a');
    link.href = deeplink;
    link.click();
    if (this.isMobile()) {
      setTimeout(() => {
        if (!document.hidden) {
          alert('Vui lòng mở ứng dụng ngân hàng thủ công và quét mã QR');
        }
      }, 2000);
    }
  }
  isMobile(): boolean {
    return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
      navigator.userAgent
    );
  }
  formatAmount(amount: number): string {
    return new Intl.NumberFormat('vi-VN', {
      style: 'currency',
      currency: 'VND',
    }).format(amount);
  }
}
export const paymentService = new PaymentService();
